using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using TeeSheet.Domain;

namespace TeeSheet.Infrastructure.Persistence.Configurations;

internal sealed class TeeTimeConfiguration : IEntityTypeConfiguration<TeeTime>
{
    public void Configure(EntityTypeBuilder<TeeTime> builder)
    {
        builder.ToTable("TeeTimes");
        builder.HasKey(t => t.TeeTimeId);

        builder.Property(t => t.StartUtc).HasColumnType("datetime2(0)");
        builder.Property(t => t.Price).HasPrecision(8, 2);

        // ROWVERSION column: generated by SQL Server and used as the optimistic concurrency token.
        builder.Property(t => t.RowVersion).IsRowVersion();

        builder.HasOne(t => t.Course)
            .WithMany(c => c.TeeTimes)
            .HasForeignKey(t => t.CourseId)
            .OnDelete(DeleteBehavior.Restrict);
    }
}
